  "× closes it. If nobody takes it, it can come back as Exclusive.": "× la ferme. Si personne ne la prend, elle peut revenir en Exclusif.",
  "×{0} is a high surge. Riders pay {1} times the normal trip price.": "×{0} est une forte majoration. Les passagers paient {1} fois le prix normal.",
  "×{0} running": "×{0} en cours",
  "×1.3 means 30% more on the driver's share of each fare. Needs a max payout.": "×1,3 signifie 30 % de plus sur la part du chauffeur de chaque course. Nécessite un versement maximum.",
