  "That point is in no zone.": "Ce point n’est dans aucune zone.",
  "That record is outside your active scope.": "Cette fiche est hors de votre périmètre actif.",
  "That revision is already live.": "Cette révision est déjà en ligne.",
  "That version has no such zone.": "Cette version n’a pas cette zone.",
  "That version was not found.": "Cette version est introuvable.",
  "The acceptance rate counts only Exclusive and other one-driver offers. Radar trips never count.": "Le taux d’acceptation ne compte que les offres exclusives et les autres offres à un seul chauffeur. Les courses Radar ne comptent jamais.",
  "The biggest refund each role can give at all; above it, a role with a higher limit must do it. The Super admin has no limit. When a refund needs a second admin is one limit per country in Settings.": "Le plus gros remboursement que chaque rôle peut accorder ; au-delà, un rôle avec une limite plus haute doit le faire. Le Super admin n’a pas de limite. Le besoin d’un second admin pour un remboursement est une limite par pays dans Paramètres.",
  "The cancel rate a driver should stay under. A normal-trip cancel only counts in the cancel rate: no pause and no fee.": "Le taux d’annulation sous lequel un chauffeur doit rester. Une annulation de course normale ne compte que dans le taux d’annulation : pas de pause ni de frais.",
  "The car broke down": "La voiture est tombée en panne",
  "The car is far from the planned route.": "La voiture est loin de l’itinéraire prévu.",
  "The car stands still mid-trip, not at a planned stop and not in traffic. Ride check starts.": "La voiture est immobile en pleine course, pas à un arrêt prévu et pas dans les bouchons. Le contrôle de course commence.",
  "The card cannot be closed until the person answers. Movera never calls 112; the person calls. Every check is in {0}.": "La fiche ne peut pas être fermée tant que la personne n’a pas répondu. Movera n’appelle jamais le 112 ; c’est la personne qui appelle. Chaque contrôle est dans {0}.",
  "The code needs 2–12 capital letters, digits or dashes.": "Le code nécessite 2 à 12 majuscules, chiffres ou tirets.",
  "The default for {0} is {1}, set in Settings › Payment methods and languages per country. Your choice is saved for you only.": "La langue par défaut pour {0} est {1}, réglée dans Paramètres › Moyens de paiement et langues par pays. Votre choix n’est enregistré que pour vous.",
  "The draft now": "Le brouillon actuel",
  "The driver · bank •••• {0}": "Le chauffeur · banque •••• {0}",
  "The driver always gets the total. You choose if the card also shows the pickup part.": "Le chauffeur reçoit toujours le total. Vous choisissez si la fiche montre aussi la part d’approche.",
  "The driver and rider apps ask \"Is everything OK?\" when a trip looks wrong. Accident, Someone hurt or I feel unsafe sends you an alert.": "Les applis chauffeur et passager demandent « Tout va bien ? » quand une course semble anormale. Accident, Quelqu’un est blessé ou Je ne me sens pas en sécurité vous envoie une alerte.",
  "The driver and rider apps use the new values on the next trip.": "Les applis chauffeur et passager utilisent les nouvelles valeurs à la prochaine course.",
  "{0} Leave now: the driver app's estimated drive time to the pickup + spare minutes (an estimate, not live traffic). Then the ride always lands on the driver's screen as the active trip with Head to pickup, even if they were driving away.": "{0} Partir maintenant : le temps de trajet estimé par l’app chauffeur jusqu’à la prise en charge + minutes de marge (une estimation, pas le trafic en direct). La course arrive alors toujours sur l’écran du chauffeur comme course active avec Se diriger vers la prise en charge, même s’il s’éloignait.",
  "The driver asked me to leave the car": "Le chauffeur m’a demandé de quitter la voiture",
  "The driver came {0}% closer ({1} → {2} km). Fee applies.": "Le chauffeur s’est rapproché de {0} % ({1} → {2} km). Des frais s’appliquent.",
  "The driver came only {0}% closer (needs {1}%). No fee.": "Le chauffeur ne s’est rapproché que de {0} % (il faut {1} %). Pas de frais.",
  "The driver collects the fare in cash at the drop-off.": "Le chauffeur encaisse le tarif en espèces à la dépose.",
  "The driver drove far to get the rider: for example a shorter free wait and a higher no-show fee.": "Le chauffeur a fait un long trajet pour aller chercher le passager : par exemple une attente gratuite plus courte et des frais d’absence plus élevés.",
  "The driver is offline": "Le chauffeur est hors ligne",
  "The driver or rider tapped Accident, Someone hurt or I feel unsafe. A later Yes or Not sure updates it. A red banner shows on every page until an admin opens it. Taken and solved in Incidents.": "Le chauffeur ou le passager a appuyé sur Accident, Quelqu’un est blessé ou Je ne me sens pas en sécurité. Un Oui ou Pas sûr ultérieur la met à jour. Un bandeau rouge s’affiche sur chaque page jusqu’à ce qu’un admin l’ouvre. Prise et résolue dans Incidents.",
  "The driver sees “Rest until 04:30” and can go online again after {0} h of rest.": "Le chauffeur voit « Repos jusqu’à 04:30 » et peut se remettre en ligne après {0} h de repos.",
  "The driver sees only these in the app and can switch some of them off, for example drive Comfort but not Movera. Offers follow the driver's choice. The driver can never switch on a category that is off here.": "Le chauffeur ne voit que celles-ci dans l’appli et peut en désactiver certaines, par exemple conduire Confort mais pas Movera. Les offres suivent le choix du chauffeur. Le chauffeur ne peut jamais activer une catégorie désactivée ici.",
  "The driver taps Finish far from the drop-off. Ride check starts right after finish.": "Le chauffeur appuie sur Terminer loin de la dépose. Le contrôle de course commence juste après.",
  "The driver taps Finish this far from the drop-off point. Ride check starts right after finish.": "Le chauffeur appuie sur Terminer à cette distance du point de dépose. Le contrôle de course commence juste après.",
  "The driver's share, after Movera's commission.": "La part du chauffeur, après la commission de Movera.",
  "The driver's zone": "La zone du chauffeur",
  "The end day must be after the start day.": "Le jour de fin doit être après le jour de début.",
  "The file has no shape (Polygon).": "Le fichier n’a pas de forme (Polygon).",
