  "The live price controls (fare ±15%, waiting time).": "Les contrôles de prix en direct (tarif ±15 %, temps d’attente).",
  "The map is hidden. Everything else still works.": "La carte est masquée. Tout le reste fonctionne.",
  "The map needs WebGL, which this browser has turned off. Drivers online:": "La carte nécessite WebGL, désactivé dans ce navigateur. Chauffeurs en ligne :",
  "The map needs WebGL, which this browser has turned off. Pick a place in the list instead.": "La carte nécessite WebGL, désactivé dans ce navigateur. Choisissez plutôt un lieu dans la liste.",
  "The map needs WebGL, which this browser has turned off. Surge by zone:": "La carte nécessite WebGL, désactivé dans ce navigateur. Majoration par zone :",
  "The map needs WebGL, which this browser has turned off. The stops are listed below.": "La carte nécessite WebGL, désactivé dans ce navigateur. Les arrêts sont listés ci-dessous.",
  "The most an admin can add to one trip for the driver. Movera pays it; the rider never does. Above it the admin sees “adjust the limit in Pricing”.": "Le maximum qu’un admin peut ajouter sur une course pour le chauffeur. Movera le paie ; jamais le passager. Au-delà, l’admin voit « ajuster la limite dans Tarifs ».",
  "The most one driver can earn": "Le maximum qu’un chauffeur peut gagner",
  "The nearest available driver gets it as an Exclusive offer.": "Le chauffeur disponible le plus proche la reçoit en offre exclusive.",
  "The nearest suitable drivers, all at the same time.": "Les chauffeurs adaptés les plus proches, tous en même temps.",
  "The other admin becomes the one working on it.": "L’autre admin devient celui qui s’en occupe.",
  "The owed amount is taken from the driver's next payout. {0}": "Le montant dû est prélevé sur le prochain versement du chauffeur. {0}",
  "The pay change waits for a second admin.": "Le changement de rémunération attend un second admin.",
  "The payment did not go through. Retries are listed.": "Le paiement n’est pas passé. Les nouvelles tentatives sont listées.",
  "The pickup is outside the event area{0}. Normal rules are used.": "La prise en charge est hors de la zone de l’événement{0}. Les règles normales s’appliquent.",
  "The pickup zone": "La zone de prise en charge",
  "The price minus Movera's commission.": "Le prix moins la commission de Movera.",
  "The ride price minus Movera's commission (and the fleet owner's share), plus the tip.": "Le prix de la course moins la commission de Movera (et la part du propriétaire de flotte), plus le pourboire.",
  "The ride shows in Live and in Alerts as “Booked ride soon with no driver”, so you can give it to a driver.": "La course s’affiche dans En direct et dans Alertes comme « Course réservée bientôt sans chauffeur », pour que vous puissiez la donner à un chauffeur.",
  "The ride shows in Live with an alert, so an admin can pick a driver.": "La course s’affiche dans En direct avec une alerte, pour qu’un admin choisisse un chauffeur.",
  "The rider asked for a stop": "Le passager a demandé un arrêt",
  "The rider asked for another route": "Le passager a demandé un autre itinéraire",
  "The rider asked to stop here": "Le passager a demandé à s’arrêter ici",
  "The rider asks for{0}": "Le passager demande{0}",
  "The rider can wait more minutes or stop.": "Le passager peut attendre plus longtemps ou arrêter.",
  "The rider changed destination": "Le passager a changé de destination",
  "The rider has waited long": "Le passager a longtemps attendu",
  "The rider marked this driver as a favourite.": "Le passager a mis ce chauffeur en favori.",
  "The rider only sees “Searching” until a driver accepts. Click a driver’s name to send an exclusive offer, or tick up to {0} drivers and send them to the radar. Repeat until someone accepts.": "Le passager ne voit que « Recherche » jusqu’à ce qu’un chauffeur accepte. Cliquez sur le nom d’un chauffeur pour envoyer une offre exclusive, ou cochez jusqu’à {0} chauffeurs et envoyez-les au radar. Recommencez jusqu’à ce que quelqu’un accepte.",
  "The rider pays the same. The next driver earns more, so it is taken faster.": "Le passager paie la même chose. Le chauffeur suivant gagne plus, donc la course est prise plus vite.",
  "The rider saw the busy message.": "Le passager a vu le message d’affluence.",
  "The rider sees “Searching”. See the active drivers near the pickup to send an exclusive offer to one, or a radar group of up to 10.{0}": "Le passager voit « Recherche ». Voyez les chauffeurs actifs près de la prise en charge pour envoyer une offre exclusive à l’un d’eux, ou à un groupe radar de 10 au plus.{0}",
  "The rider shares trips with nobody.": "Le passager ne partage ses courses avec personne.",
  "The rider was left at the wrong place": "Le passager a été déposé au mauvais endroit",
  "The rider's bank asks for proof. Answer before the deadline or the money goes back to the rider. The trip page has the route, chat and calls to use as proof.": "La banque du passager demande un justificatif. Répondez avant l’échéance, sinon l’argent revient au passager. La page de la course contient l’itinéraire, la discussion et les appels à utiliser comme justificatif.",
  "The rider's bank questions the payment (chargeback).": "La banque du passager conteste le paiement (rétrofacturation).",
  "The riders who joined last.": "Les passagers inscrits en dernier.",
  "The search grows step by step when nobody accepts.": "La recherche s’élargit étape par étape quand personne n’accepte.",
  "The search stops and the rider sees this message.": "La recherche s’arrête et le passager voit ce message.",
  "The server could not be reached to confirm it.": "Le serveur n’a pas pu être joint pour le confirmer.",
  "The server has no record of it, so nothing changed.": "Le serveur n’en a aucune trace, donc rien n’a changé.",
  "The server is taking longer than usual; this updates to Done or Failed.": "Le serveur met plus de temps que d’habitude ; ceci passera à Terminé ou Échec.",
  "The shape stays inside the city.": "La forme reste dans la ville.",
  "The short text on an Exclusive offer that says why it is for this driver. Keep it short and professional, at most {0} characters. Off: no reason text.": "Le court texte sur une offre exclusive qui dit pourquoi elle est pour ce chauffeur. Restez bref et professionnel, {0} caractères au plus. Désactivé : pas de texte de motif.",
  "The smart cancel check is off in this zone (Rider cancels: smart check), so live trips have no cancel fee.": "Le contrôle intelligent des annulations est désactivé dans cette zone (Le passager annule : contrôle intelligent), donc les courses en direct n’ont pas de frais d’annulation.",
  "The smart cancel check is off in this zone.": "Le contrôle intelligent des annulations est désactivé dans cette zone.",
  "The step the time before pickup says, as if nobody had taken it.": "L’étape que donne le temps avant la prise en charge, comme si personne ne l’avait prise.",
  "The system compares the driver's distance to the rider when they accepted and when the rider cancelled.": "Le système compare la distance du chauffeur au passager au moment de l’acceptation et au moment de l’annulation.",
  "The system decides the fee by comparing the driver's distance to the rider when they accepted and when the rider cancelled. If a driver complains, open the record and change the decision.": "Le système décide des frais en comparant la distance du chauffeur au passager au moment de l’acceptation et de l’annulation. Si un chauffeur conteste, ouvrez la fiche et changez la décision.",
