  "Welcome to Movera": "Bienvenue chez Movera",
  "What a fleet owner gets from their drivers' rides, after commission.": "Ce qu’un propriétaire de flotte reçoit des courses de ses chauffeurs, après commission.",
  "What a new driver must upload in this country. The driving licence is always needed.": "Ce qu’un nouveau chauffeur doit envoyer dans ce pays. Le permis de conduire est toujours requis.",
  "What an admin picks when cancelling a trip from Trips. The codes are fixed by the shared contract.": "Ce qu’un admin choisit en annulant une course depuis Courses. Les codes sont fixés par le contrat partagé.",
  "What changed": "Ce qui a changé",
  "What drivers and riders choose from when they cancel. Mark a reason “Doesn't count” and it never hurts the cancel rate or the late-cancel rule, for example a rider no-show, safety or a car problem. An empty language shows the English text.": "Ce que chauffeurs et passagers choisissent quand ils annulent. Marquez un motif « Ne compte pas » et il ne pénalise jamais le taux d’annulation ni la règle d’annulation tardive, par exemple une absence du passager, la sécurité ou un problème de véhicule. Une langue vide affiche le texte anglais.",
  "What happened, what you did": "Ce qui s’est passé, ce que vous avez fait",
  "What happens second by second": "Ce qui se passe seconde par seconde",
  "What is {0}?": "Qu’est-ce que {0} ?",
  "What is it about?": "De quoi s’agit-il ?",
  "What is needed?": "Qu’est-ce qui est nécessaire ?",
  "What is the case about": "Sur quoi porte le dossier",
  "What is wrong?": "Qu’est-ce qui ne va pas ?",
  "What makes the best driver": "Ce qui fait le meilleur chauffeur",
  "What Movera keeps from the trip price": "Ce que Movera garde du prix de la course",
  "What riders paid on average for completed trips, before tips.": "Ce que les passagers ont payé en moyenne pour les courses terminées, avant pourboires.",
  "What the driver sees before accepting, on the Radar card, the Exclusive card and the reservation popup. Switch each detail on or off.": "Ce que le chauffeur voit avant d’accepter, sur la fiche Radar, la fiche Exclusif et la fenêtre de réservation. Activez ou désactivez chaque détail.",
  "What the driver sees, {0}": "Ce que voit le chauffeur, {0}",
  "What the driver's offer card shows": "Ce que montre la fiche de l’offre du chauffeur",
  "What the rider app asks when the rider cancels.": "Ce que l’appli passager demande quand le passager annule.",
  "What the rider can pay with, and the language each app starts in. The same four methods are offered in every country; untick one to turn it off there. The wallet stays: one balance per currency, used first (Features › Wallet).": "Ce avec quoi le passager peut payer, et la langue de démarrage de chaque appli. Les quatre mêmes moyens sont proposés dans chaque pays ; décochez-en un pour le désactiver là-bas. Le portefeuille reste : un solde par devise, utilisé en premier (Fonctions › Portefeuille).",
  "What the rider sees while waiting": "Ce que voit le passager pendant l’attente",
  "What to copy": "Quoi copier",
  "What was done (optional)": "Ce qui a été fait (facultatif)",
