  "When": "Quand",
  "When a driver declines or ignores an offer.": "Quand un chauffeur refuse ou ignore une offre.",
  "When a driver takes it, it disappears at once from every other driver's app. If that driver cancels {0} before pickup, it goes back out as {1}.{2}": "Quand un chauffeur la prend, elle disparaît aussitôt de l’appli de tous les autres chauffeurs. Si ce chauffeur annule {0} avant la prise en charge, elle repart en {1}.{2}",
  "When an applicant has not done their part, the app reminds them.": "Quand un candidat n’a pas fait sa part, l’appli le lui rappelle.",
  "When busy, collect requests for a few seconds and match them together for the best fit.": "En cas d’affluence, rassembler les demandes quelques secondes et les attribuer ensemble pour la meilleure correspondance.",
  "When drivers get paid": "Quand les chauffeurs sont payés",
  "When it runs {0}": "Quand elle s’exécute {0}",
  "When off, Show still works and is still logged, without a reason.": "Désactivé, Afficher fonctionne toujours et reste consigné, sans motif.",
