  "Zones in {0} {1}": "Zones en {0} {1}",
  "Zones with “Over the cancel rate limit” on in Safety send no requests to drivers over it. Reasons marked “Doesn't count” never count ({0}). Scheduled rides also follow the late-cancel rule in Reservations. The acceptance rate has no rules.": "Les zones où « Au-delà de la limite du taux d’annulation » est activé dans Sécurité n’envoient pas de demandes aux chauffeurs au-delà. Les motifs marqués « Ne compte pas » ne comptent jamais ({0}). Les courses réservées suivent aussi la règle d’annulation tardive des Réservations. Le taux d’acceptation n’a pas de règles.",
  "Zones, airports and zone rules": "Zones, aéroports et règles de zone",
  "Zones: {0}": "Zones : {0}",
  "Zoom in": "Zoom avant",
  "Zoom out": "Zoom arrière",
  // Radar · Exclusive · Reservations
  "A rule applies to all radar zones, several or one. The rule follows the radar zone the ride was sent to, never where a driver stands, so overlapping zones never clash. A rule naming a radar zone wins over the rule for all of them.": "Une règle s’applique à toutes les zones radar, à plusieurs ou à une seule. La règle suit la zone radar vers laquelle la course a été envoyée, jamais l’endroit où se trouve un chauffeur : des zones qui se chevauchent n’entrent donc jamais en conflit. Une règle qui nomme une zone radar l’emporte sur la règle pour toutes.",
  "All radar zones": "Toutes les zones radar",
  "Applies to: {0}": "S’applique à : {0}",
  "Applies to{0}": "S’applique à{0}",
  "Areas inside the zone, drawn on the map and saved. From Live or the Dashboard a waiting ride can be put on the radar of one area: the free drivers inside it see it. Zones are independent and may overlap, so start small and widen if nobody accepts. The whole zone needs no radar zone.": "Des secteurs dans la zone, dessinés sur la carte et enregistrés. Depuis Live ou le Tableau de bord, une course en attente peut être mise sur le radar d’un secteur : les chauffeurs libres qui s’y trouvent la voient. Les secteurs sont indépendants et peuvent se chevaucher : commencez petit, puis élargissez si personne n’accepte. La zone entière n’a pas besoin de zone radar.",
  "Different limit while driving": "Limite différente en roulant",
  "Each zone has its own Radar and Exclusive rules, its radar zones drawn on the map, and what the driver app shows.": "Chaque zone a ses propres règles Radar et Exclusif, ses zones radar dessinées sur la carte, et ce que l’app chauffeur affiche.",
  "Each zone has its own rules: the best driver, what the rider sees while waiting, rides and stops, and more. Radar, Exclusive and reservations have their own section.": "Chaque zone a ses propres règles : le meilleur chauffeur, ce que le passager voit en attendant, courses et arrêts, et plus. Radar, Exclusif et réservations ont leur propre section.",
  "Every Radar, Exclusive and reservation rule is set there, in one place.": "Toutes les règles Radar, Exclusif et réservations se règlent là, en un seul endroit.",
  "Every offer rule in one place: Radar and its radar zones, Exclusive, and reservations, for every zone.": "Toutes les règles d’offre en un seul endroit : Radar et ses zones radar, Exclusif et réservations, pour chaque zone.",
  "For example Friday nights": "Par exemple Vendredis soir",
  "For example Södermalm": "Par exemple Södermalm",
  "How long the request stays before the next step. A radar group sent from Live or the Dashboard counts down this time too.": "Combien de temps la demande reste avant l’étape suivante. Un groupe radar envoyé depuis Live ou le Tableau de bord décompte aussi ce temps.",
  "How ride requests find a driver, with rules for every zone. Radar, Exclusive and reservations have their own section.": "Comment les demandes de course trouvent un chauffeur, avec des règles pour chaque zone. Radar, Exclusif et réservations ont leur propre section.",
  "Lock the full-screen list while driving": "Verrouiller la liste plein écran en roulant",
  "Most cards at the same time while the car is stopped.": "Nombre maximal de cartes en même temps à l’arrêt.",
  "Most cards at the same time, all the time.": "Nombre maximal de cartes en même temps, tout le temps.",
  "Most drivers who see it{0}": "Chauffeurs maximum qui la voient{0}",
  "Most rides shown in the list at once.": "Nombre maximal de courses affichées dans la liste à la fois.",
  "New radar zone": "Nouvelle zone radar",
  "No radar zone": "Aucune zone radar",
  "No radar zone yet in {0}.": "Pas encore de zone radar dans {0}.",
  "No radar zone yet. Draw one first.": "Pas encore de zone radar. Dessinez-en une d’abord.",
  "Offer cards while driving": "Cartes d’offre en roulant",
  "On: the cards have their own limit while the car is moving with no rider. Off: one number all the time.": "Activé : les cartes ont leur propre limite quand la voiture roule sans passager. Désactivé : un seul nombre tout le temps.",
  "Pick radar zones": "Choisir des zones radar",
  "Radar zone": "Zone radar",
  "Radar zone name": "Nom de la zone radar",
